def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        total = 0
        has_numeric = False
        for row in rows:
            if i < len(row):
                val = row[i]
                if isinstance(val, (int, float)):
                    total += val
                    has_numeric = True
        if has_numeric:
            totals.append(total)
        else:
            totals.append("")
    return totals

def render_rows(rows, mark_last=False):
    result = []
    for i, r in enumerate(rows):
        line = ",".join(str(v) for v in r)
        if mark_last and i == len(rows) - 1:
            line = "TOTAL," + line
        result.append(line)
    return result
